 IF (SELECT max(event_id) FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='USER_STOP_REQUESTED') IS DISTINCT FROM 9527::bigint THEN RAISE EXCEPTION 'Later/unknown user stop'; END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE ended_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_attempt WHERE status NOT IN('COMPLETE','FAILED','EXPIRED')) OR EXISTS(SELECT 1 FROM cron.job WHERE jobid IN(596,597) AND active) THEN RAISE EXCEPTION 'Active operations or schedule; reconcile'; END IF;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('USER_AUTHORITY_RESUMED_20261024',jsonb_build_object('owner_id',new_owner,'owner_fence',3,'stop_generation',1,'scope_sha256',a.scope_sha256,'previous_owner',a.owner_id,'previous_fence',a.owner_fence,'resumed_stop_event_id',9527,'monetary_cap_removed',true,'historical_cap_usd',p.budget_cap_usd,'authority','Rob explicit 24 October 2026 instruction resumes only this mission, removes USD250 cap, and authorizes required historical licenses, purchases, compute, storage, transfer, API/model use, scoped implementation and deployments. Finite operational, provider, ownership, stop and unrelated-service protections remain.','prompt00_sha256','6f6774d1cce7d5601cf42120bdf20f9130b4982320aad0d7e9f0f74be7f9f5c6','prior_budget_evidence',p.budget_evidence,'prior_counters',jsonb_build_object('stored_bytes',a.stored_bytes,'http_invocations',a.http_invocations,'provider_requests',a.provider_requests,'dispatch_calls',a.dispatch_calls,'tick_count',p.tick_count,'actual_usd',p.actual_usd,'accrued_usd',p.accrued_usd,'unavoidable_usd',p.unavoidable_usd,'reserved_request_usd',p.reserved_request_usd,'remaining_uncommitted_usd',p.remaining_uncommitted_usd,'repair_egress_reserve_usd',p.repair_egress_reserve_usd),'original_deadline',p.deadline,'no_inflight_tasks_or_provider_leases',true,'runtime_cost_policy_patch_pending',true)) RETURNING event_id INTO eid;
