 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('ENGINEERING_ASSIGNMENT_DISPATCHED',item||jsonb_build_object('assignment_id','completion-20261024-prompt'||(item->>'prompt'),'owner_id',new_owner,'owner_fence',3,'stop_generation',1,'authority_event_id',eid,'scope_sha256',a.scope_sha256,'allowed_actions','Read-only live/provider evidence and isolated implementation/tests; root integrates production mutations','review_required',true,'result_channel','pipeline_event ENGINEERING_ASSIGNMENT_RESULT pinned repository artifacts','successor','independent review then root integration and useful-data proof','initial_work_bound_minutes',60,'initial_source_probe_call_bound',25));
